package com.recgombak.batterymonitor;

import android.app.*;import android.content.*;import android.graphics.*;import android.media.*;import android.net.DhcpInfo;import android.net.wifi.WifiManager;import android.os.*;import android.provider.Settings;import android.text.InputType;import android.view.*;import android.widget.*;import org.json.JSONObject;import java.net.*;import java.nio.charset.StandardCharsets;

public class BatteryBroadcastService extends Service{
 public static final int PORT=45888;private static final String CHANNEL_ID="rec_battery_status",TIMER_CHANNEL="rec_timer_alarm_v4",CHARGE_CHANNEL="rec_charge_alarm_v2";private volatile boolean running=false;private Thread worker,commandWorker;private long lastTimerEnd=0,lastChargeBackupCheck=0;private WindowManager wm;private View overlay;private BroadcastReceiver batteryReceiver;
 @Override public void onCreate(){super.onCreate();createChannels();registerBatteryReceiver();startForeground(1001,buildNotification(getBatteryPercent(),isCharging()));}
 private void registerBatteryReceiver(){batteryReceiver=new BroadcastReceiver(){@Override public void onReceive(Context c,Intent i){String a=i==null?"":i.getAction();if(Intent.ACTION_BATTERY_CHANGED.equals(a)||Intent.ACTION_POWER_CONNECTED.equals(a)||Intent.ACTION_POWER_DISCONNECTED.equals(a)){checkLocalChargeAlarm();updateNotification(getBatteryPercent(),isCharging());if(Prefs.inSchedule(BatteryBroadcastService.this))sendStatus();}}};IntentFilter f=new IntentFilter();f.addAction(Intent.ACTION_BATTERY_CHANGED);f.addAction(Intent.ACTION_POWER_CONNECTED);f.addAction(Intent.ACTION_POWER_DISCONNECTED);try{registerReceiver(batteryReceiver,f);}catch(Exception ignored){}}
 @Override public int onStartCommand(Intent i,int f,int id){if(i!=null&&"ACK_LOCAL".equals(i.getAction())){dismissLocalAlarm();sendStatus();}if(i!=null&&"UNLOCK_LOCAL".equals(i.getAction())){clearTimerRecord();Prefs.setTimerLockMode(this,false);sendStatus();}if(!Prefs.isEnabled(this)){stopSelf();return START_NOT_STICKY;}if(!running){running=true;worker=new Thread(this::loop,"REC-Battery-Broadcast");worker.start();commandWorker=new Thread(this::listenCommands,"REC-Commands");commandWorker.start();}return START_STICKY;}
 private void loop(){while(running){try{checkTimer();long now=System.currentTimeMillis();if(now-lastChargeBackupCheck>=120000L){lastChargeBackupCheck=now;checkLocalChargeAlarm();}if(Prefs.inSchedule(this))sendStatus();updateNotification(getBatteryPercent(),isCharging());}catch(Exception ignored){}try{long sleep="tablet".equals(Prefs.getRole(this))?Math.max(15000L,Prefs.getInterval(this)*1000L):Math.max(5000L,Prefs.getInterval(this)*1000L);Thread.sleep(sleep);}catch(InterruptedException e){break;}}}
 private synchronized void checkLocalChargeAlarm(){if(!"tablet".equals(Prefs.getRole(this))||!Prefs.localChargeAlarmEnabled(this))return;int battery=getBatteryPercent(),threshold=Prefs.getLocalChargeThreshold(this);boolean charging=isCharging();if(!charging||battery<threshold){Prefs.setLocalChargeAlarmed(this,false);Prefs.setLocalChargeLastAlarm(this,0);return;}long now=System.currentTimeMillis();if(Prefs.localChargeAlarmOnce(this)){if(Prefs.isLocalChargeAlarmed(this))return;Prefs.setLocalChargeAlarmed(this,true);}else{long last=Prefs.getLocalChargeLastAlarm(this);if(last>0&&now-last<60000L)return;Prefs.setLocalChargeLastAlarm(this,now);}playAlarm(Prefs.getLocalAlarmSeconds(this)*1000);showChargeNotification(battery,threshold);}
 private void checkTimer(){long end=Prefs.getTimerEnd(this);if(end!=lastTimerEnd){lastTimerEnd=end;if(end>System.currentTimeMillis())Prefs.setTimerAlarmed(this,false);}if(end>0&&System.currentTimeMillis()>=end&&!Prefs.isTimerAlarmed(this)){Prefs.setTimerAlarmed(this,true);Prefs.setTimerDone(this,true);playAlarm(7000);showTimerNotification();showTimeUp();sendStatus();}else if(Prefs.isTimerDone(this)&&Prefs.isTimerLockMode(this)&&overlay==null)showTimeUp();}
 private void showTimeUp(){if(Build.VERSION.SDK_INT>=23&&Settings.canDrawOverlays(this)){new Handler(Looper.getMainLooper()).post(this::showOverlay);}else openTimeUpScreen();}
 private void showOverlay(){if(overlay!=null)return;try{wm=(WindowManager)getSystemService(WINDOW_SERVICE);LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setGravity(Gravity.CENTER);box.setPadding(dp(28),dp(28),dp(28),dp(28));box.setBackgroundColor(Color.rgb(180,0,0));box.addView(text("⛔",72,true));box.addView(text("MASA TAMAT",36,true));TextView sub=text(Prefs.isTimerLockMode(this)?"Tablet dikunci. Password cikgu diperlukan.":"Masa penggunaan tablet telah tamat.",20,false);sub.setPadding(0,dp(14),0,dp(28));box.addView(sub);Button ok=new Button(this);ok.setText(Prefs.isTimerLockMode(this)?"🔐 BUKA KUNCI":"OK");ok.setTextSize(20);ok.setOnClickListener(v->{if(Prefs.isTimerLockMode(this))showPinDialog();else{dismissLocalAlarm();sendStatus();}});box.addView(ok,new LinearLayout.LayoutParams(-1,dp(60)));int type=Build.VERSION.SDK_INT>=26?WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY:WindowManager.LayoutParams.TYPE_PHONE;WindowManager.LayoutParams lp=new WindowManager.LayoutParams(-1,-1,type,WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN|WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON,PixelFormat.TRANSLUCENT);overlay=box;wm.addView(overlay,lp);}catch(Exception e){overlay=null;openTimeUpScreen();}}
 private void showPinDialog(){new Handler(Looper.getMainLooper()).post(()->{EditText e=new EditText(this);e.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD);e.setHint("Password");AlertDialog d=new AlertDialog.Builder(this).setTitle("Buka Kunci Tablet").setView(e).setPositiveButton("BUKA",null).setNegativeButton("Batal",null).create();d.setOnShowListener(x->d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{if(e.getText().toString().equals(Prefs.getTimerPin(this))){clearTimerRecord();Prefs.setTimerLockMode(this,false);sendStatus();d.dismiss();}else Toast.makeText(this,"Password salah",Toast.LENGTH_LONG).show();}));try{if(Build.VERSION.SDK_INT>=26)d.getWindow().setType(WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY);d.show();}catch(Exception ex){openTimeUpScreen();}});}
 private TextView text(String s,int size,boolean bold){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(Color.WHITE);v.setGravity(Gravity.CENTER);if(bold)v.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return v;}private int dp(int v){return(int)(v*getResources().getDisplayMetrics().density+.5f);}
 private void removeOverlay(){new Handler(Looper.getMainLooper()).post(()->{try{if(overlay!=null&&wm!=null)wm.removeView(overlay);}catch(Exception ignored){}overlay=null;});}
 private void dismissLocalAlarm(){removeOverlay();((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).cancel(2002);}
 private void clearTimerRecord(){Prefs.setTimerEnd(this,0);Prefs.setTimerAlarmed(this,false);Prefs.setTimerDone(this,false);lastTimerEnd=0;dismissLocalAlarm();}
 private void openTimeUpScreen(){try{Intent i=new Intent(this,TimeUpActivity.class);i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);startActivity(i);}catch(Exception ignored){}}
 private void playAlarm(int ms){new Thread(()->{ToneGenerator tg=null;try{AudioManager am=(AudioManager)getSystemService(AUDIO_SERVICE);am.setStreamVolume(AudioManager.STREAM_ALARM,am.getStreamMaxVolume(AudioManager.STREAM_ALARM),0);tg=new ToneGenerator(AudioManager.STREAM_ALARM,100);long until=System.currentTimeMillis()+Math.max(1000,ms);while(System.currentTimeMillis()<until){tg.startTone(ToneGenerator.TONE_CDMA_ALERT_CALL_GUARD,900);Thread.sleep(1000);}}catch(Exception ignored){}finally{if(tg!=null)tg.release();}}).start();}
 private void showTimerNotification(){Intent open=new Intent(this,TimeUpActivity.class);PendingIntent pi=PendingIntent.getActivity(this,77,open,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,TIMER_CHANNEL):new Notification.Builder(this);Notification n=b.setContentTitle(Prefs.isTimerLockMode(this)?"TABLET DIKUNCI":"MASA TAMAT").setContentText(Prefs.getName(this)+" — masa penggunaan telah tamat").setSmallIcon(android.R.drawable.ic_lock_idle_alarm).setContentIntent(pi).setFullScreenIntent(pi,true).setAutoCancel(false).setPriority(Notification.PRIORITY_MAX).setCategory(Notification.CATEGORY_ALARM).build();((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(2002,n);}
 private void showChargeNotification(int battery,int threshold){Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,CHARGE_CHANNEL):new Notification.Builder(this);Notification n=b.setContentTitle("🔋 CAS MENCUKUPI").setContentText(Prefs.getName(this)+" — "+battery+"% (had "+threshold+"%). Cabut pengecas.").setSmallIcon(android.R.drawable.ic_lock_idle_charging).setAutoCancel(true).setPriority(Notification.PRIORITY_HIGH).setCategory(Notification.CATEGORY_ALARM).build();((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(3003,n);}
 private void sendStatus(){try{JSONObject o=new JSONObject();o.put("app","REC_BATTERY_V12");o.put("type","status");o.put("id",Prefs.getId(this));o.put("name",Prefs.getName(this));o.put("model",Build.MANUFACTURER+" "+Build.MODEL);o.put("battery",getBatteryPercent());o.put("charging",isCharging());o.put("timerEnd",Prefs.getTimerEnd(this));o.put("timerDone",Prefs.isTimerDone(this));o.put("timerLockMode",Prefs.isTimerLockMode(this));o.put("scheduleOn",Prefs.scheduleOn(this));o.put("startMin",Prefs.getStartMin(this));o.put("endMin",Prefs.getEndMin(this));o.put("ts",System.currentTimeMillis());send(o);}catch(Exception ignored){}}
 private void listenCommands(){try(DatagramSocket s=new DatagramSocket(null)){s.setReuseAddress(true);s.setBroadcast(true);s.bind(new InetSocketAddress(PORT+1));s.setSoTimeout(3000);byte[] buf=new byte[2048];while(running){try{DatagramPacket p=new DatagramPacket(buf,buf.length);s.receive(p);JSONObject o=new JSONObject(new String(p.getData(),p.getOffset(),p.getLength(),StandardCharsets.UTF_8));String app=o.optString("app");if(!app.startsWith("REC_BATTERY_V"))continue;String target=o.optString("target","ALL");if(!"ALL".equals(target)&&!Prefs.getId(this).equals(target))continue;String cmd=o.optString("cmd");if("refresh".equals(cmd))sendStatus();else if("timer".equals(cmd)){Prefs.setTimerEnd(this,System.currentTimeMillis()+Math.max(0,o.optInt("minutes",0))*60000L);Prefs.setTimerAlarmed(this,false);Prefs.setTimerDone(this,false);Prefs.setTimerLockMode(this,o.optBoolean("lock",false));Prefs.setTimerPin(this,o.optString("pin",""));dismissLocalAlarm();sendStatus();}else if("clearTimer".equals(cmd)||"unlock".equals(cmd)){clearTimerRecord();Prefs.setTimerLockMode(this,false);sendStatus();}else if("schedule".equals(cmd)){Prefs.setScheduleOn(this,o.optBoolean("enabled",true));Prefs.setSchedule(this,o.optInt("startMin",450),o.optInt("endMin",1140));sendStatus();}else if("chargeConfig".equals(cmd)){Prefs.setLocalChargeAlarmEnabled(this,o.optBoolean("enabled",true));Prefs.setLocalChargeThreshold(this,o.optInt("threshold",95));Prefs.setLocalChargeAlarmOnce(this,o.optBoolean("once",true));Prefs.setLocalAlarmSeconds(this,o.optInt("seconds",7));Prefs.setLocalChargeAlarmed(this,false);Prefs.setLocalChargeLastAlarm(this,0);checkLocalChargeAlarm();sendStatus();}else if("chargeAlarm".equals(cmd)){int battery=o.optInt("battery",getBatteryPercent());int threshold=o.optInt("threshold",95);int seconds=Math.max(1,Math.min(60,o.optInt("seconds",7)));playAlarm(seconds*1000);showChargeNotification(battery,threshold);}}catch(SocketTimeoutException ignored){}catch(Exception ignored){}}}catch(Exception ignored){}}
 private void send(JSONObject o){try{byte[] d=o.toString().getBytes(StandardCharsets.UTF_8);sendPacket(d,"255.255.255.255");String sub=getSubnetBroadcast();if(sub!=null&&!"255.255.255.255".equals(sub))sendPacket(d,sub);}catch(Exception ignored){}}
 private void sendPacket(byte[] d,String a){try(DatagramSocket s=new DatagramSocket()){s.setBroadcast(true);s.send(new DatagramPacket(d,d.length,InetAddress.getByName(a),PORT));}catch(Exception ignored){}}
 @SuppressWarnings("deprecation")private String getSubnetBroadcast(){try{WifiManager w=(WifiManager)getApplicationContext().getSystemService(Context.WIFI_SERVICE);DhcpInfo d=w.getDhcpInfo();if(d==null)return null;int b=(d.ipAddress&d.netmask)|~d.netmask;byte[] q=new byte[4];for(int k=0;k<4;k++)q[k]=(byte)((b>>k*8)&255);return InetAddress.getByAddress(q).getHostAddress();}catch(Exception e){return null;}}
 private Intent batteryIntent(){return registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));}private int getBatteryPercent(){Intent i=batteryIntent();if(i==null)return-1;int l=i.getIntExtra(BatteryManager.EXTRA_LEVEL,-1),s=i.getIntExtra(BatteryManager.EXTRA_SCALE,100);return s>0?Math.round(l*100f/s):l;}private boolean isCharging(){Intent i=batteryIntent();if(i==null)return false;int s=i.getIntExtra(BatteryManager.EXTRA_STATUS,-1);return s==BatteryManager.BATTERY_STATUS_CHARGING||s==BatteryManager.BATTERY_STATUS_FULL;}
 private void createChannels(){if(Build.VERSION.SDK_INT>=26){NotificationManager nm=getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel(CHANNEL_ID,"REC Battery Monitor",NotificationManager.IMPORTANCE_LOW));NotificationChannel t=new NotificationChannel(TIMER_CHANNEL,"Timer Tamat",NotificationManager.IMPORTANCE_HIGH);t.setDescription("Penggera apabila timer tablet tamat");t.setLockscreenVisibility(Notification.VISIBILITY_PUBLIC);nm.createNotificationChannel(t);NotificationChannel c=new NotificationChannel(CHARGE_CHANNEL,"Cas Mencukupi",NotificationManager.IMPORTANCE_HIGH);c.setDescription("Penggera tempatan apabila bateri tablet yang sedang dicas mencapai had");c.setLockscreenVisibility(Notification.VISIBILITY_PUBLIC);nm.createNotificationChannel(c);}}
 private Notification buildNotification(int b,boolean c){PendingIntent pi=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);String txt=Prefs.inSchedule(this)?((b>=0?b+"%":"-")+(c?" • sedang dicas":" • pemantauan aktif")):"Di luar waktu pemantauan";Notification.Builder n=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,CHANNEL_ID):new Notification.Builder(this);return n.setContentTitle("REC Battery Monitor").setContentText(txt).setSmallIcon(android.R.drawable.ic_lock_idle_charging).setContentIntent(pi).setOngoing(true).build();}private void updateNotification(int b,boolean c){((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(1001,buildNotification(b,c));}
 @Override public void onDestroy(){running=false;removeOverlay();try{if(batteryReceiver!=null)unregisterReceiver(batteryReceiver);}catch(Exception ignored){}if(worker!=null)worker.interrupt();if(commandWorker!=null)commandWorker.interrupt();super.onDestroy();}@Override public IBinder onBind(Intent i){return null;}
}
